import csv
import io
import re


def parse_csv(raw_csv: str):
    old_limit = csv.field_size_limit()
    try:
        if len(raw_csv) > old_limit:
            csv.field_size_limit(len(raw_csv))
        records = list(csv.reader(io.StringIO(raw_csv, newline="")))
    finally:
        csv.field_size_limit(old_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    if columns:
        columns[0] = columns[0].lstrip("\ufeff")
    width = len(columns)
    if not width:
        return {"columns": [], "rows": records[1:]}

    rows = []
    for record in records[1:]:
        if len(record) < width:
            record = record + [""] * (width - len(record))
        elif len(record) > width:
            if width == 2:
                split_at = next(
                    (
                        i
                        for i in range(1, len(record))
                        if re.match(r'^\s*["\']?gst-launch(?:-\d+(?:\.\d+)*)?\b', record[i])
                    ),
                    1,
                )
                record = [",".join(record[:split_at]), ",".join(record[split_at:])]
            else:
                record = record[:width - 1] + [",".join(record[width - 1:])]
        rows.append(record)

    return {"columns": columns, "rows": rows}
